//! Creator Studio MCP tools. Calls are routed through the active, descriptor-
//! authorized Creator Studio WebView; this module never opens project storage.
use std::path::Path;

use serde_json::{json, Value};

use super::{ToolError, ToolSpec};

/// 生成的能力描述符（与宿主 include_str! 同一份资产）。能力发现是静态契约，
/// 不依赖 Studio 是否打开：MCP 直接读嵌入产物，避免“Studio 关着就查不到能力”。
const CREATOR_DESCRIPTOR_JSON: &str =
    include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../assets/creator/capabilities.json"));
/// 生成的车辆目录（2026-11-15 泛化切片）：creator_vehicle_list 的离线数据源，
/// 与宿主/Studio 消费同一份生成产物。
const CREATOR_VEHICLES_JSON: &str =
    include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../assets/creator/vehicles.json"));
/// 生成的世界参数目录（世界多样化 S4 产物）：headless 结构子集校验的数据源。
const CREATOR_WORLDS_JSON: &str =
    include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../assets/creator/worlds.json"));
/// 统一创作模板目录（PR12 §6.1）：声明式模板索引（与宿主 creator_projects.rs
/// include_str! 同一份）+ Code Game 模板索引。creator_template_list 的离线数据源。
const CREATOR_TEMPLATE_INDEX_JSON: &str =
    include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../assets/creator/templates-index.json"));
const CREATOR_CODE_TEMPLATES_JSON: &str =
    include_str!(concat!(env!("CARGO_MANIFEST_DIR"), "/../../assets/creator/code-templates-index.json"));

fn creator_descriptor() -> &'static Value {
    static DESCRIPTOR: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    DESCRIPTOR.get_or_init(|| serde_json::from_str(CREATOR_DESCRIPTOR_JSON)
        .expect("assets/creator/capabilities.json must parse (generated by scripts/generate-creator-capabilities.mjs)"))
}

fn creator_template_index() -> &'static Value {
    static INDEX: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    INDEX.get_or_init(|| serde_json::from_str(CREATOR_TEMPLATE_INDEX_JSON)
        .expect("assets/creator/templates-index.json must parse (generated by scripts/generate-creator-capabilities.mjs)"))
}

fn creator_code_template_index() -> &'static Value {
    static INDEX: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    INDEX.get_or_init(|| serde_json::from_str(CREATOR_CODE_TEMPLATES_JSON)
        .expect("assets/creator/code-templates-index.json must parse (generated by scripts/generate-creator-capabilities.mjs)"))
}

fn creator_vehicle_catalog() -> &'static Value {
    static CATALOG: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    CATALOG.get_or_init(|| serde_json::from_str(CREATOR_VEHICLES_JSON)
        .expect("assets/creator/vehicles.json must parse (generated by scripts/generate-creator-capabilities.mjs)"))
}

fn creator_worlds_catalog() -> &'static Value {
    static WORLDS: std::sync::OnceLock<Value> = std::sync::OnceLock::new();
    WORLDS.get_or_init(|| serde_json::from_str(CREATOR_WORLDS_JSON)
        .expect("assets/creator/worlds.json must parse (generated by scripts/generate-creator-capabilities.mjs)"))
}

/// E3 诊断闭环（STUDIO_AGENT_FIRST_EDITOR_SPEC §3.3）：稳定错误码 → recoveries 建议
///（同一份生成产物，Agent 与 Studio UI 同源）。无匹配返回 None。
pub(crate) fn recovery_for(code: &str) -> Option<Value> {
    creator_descriptor().get("recoveries").and_then(|recoveries| recoveries.get(code)).cloned()
}

/// 会话模块读取能力投影（gameTypes 可玩性判别）用；避免把内部函数改公开。
pub(crate) fn creator_descriptor_public() -> &'static Value {
    creator_descriptor()
}

/// 能力目录投影：与宿主 creator.capabilities.list 同形；category 过滤与
/// schemaVersion 校验在本地完成，错误码与宿主一致（映射到 invalid_argument）。
fn capabilities_payload(category: Option<&str>, schema_version: Option<u64>) -> Result<Value, ToolError> {
    if let Some(version) = schema_version {
        if version != 1 { return Err(ToolError::new("invalid_argument", "Only capability schemaVersion 1 is supported.")); }
    }
    let capabilities = creator_descriptor().get("capabilities").filter(|value| value.is_object())
        .ok_or_else(|| ToolError::new("data_unavailable", "Creator capability descriptor is unavailable."))?;
    let categories = capabilities.get("categories").and_then(Value::as_object)
        .ok_or_else(|| ToolError::new("data_unavailable", "Creator capability categories are unavailable."))?;
    match category {
        Some(category) => {
            let entry = categories.get(category).ok_or_else(|| ToolError::new("invalid_argument",
                "Unknown capability category; call without `category` to list supported categories."))?;
            let supported = categories.keys().collect::<Vec<_>>();
            Ok(json!({"schemaVersion":1,"category":category,"capabilities":entry,
                "preview":capabilities.get("preview").cloned().unwrap_or(Value::Null),"supportedCategories":supported}))
        }
        None => Ok(capabilities.clone()),
    }
}

/// 统一创作模板目录（PR12 §6.1）：声明式（templates-index.json）与 Code Game
/// （code-templates-index.json）并排输出。目录条目只是创作入口元数据，不是可执行
/// 授权：真正创建仍走 creator_project_create / creator_code_project_create，由
/// 宿主校验模板 provenance、digest、兼容性与用户授权；`source.entry` 由生成器
/// 固定为 `games/<templateId>`（绝不携带可逃逸路径）。
fn template_catalog_payload() -> Result<Value, ToolError> {
    let declarative = creator_template_index().get("templates").and_then(Value::as_array)
        .ok_or_else(|| ToolError::new("data_unavailable", "Creator template index is unavailable."))?;
    let mut templates = Vec::new();
    for entry in declarative {
        // 声明式模板的兼容性：pack slots 的 requires 能力并集（drive/fly），键序稳定。
        let mut requires: Vec<String> = entry.get("pack").and_then(|pack| pack.get("slots")).and_then(Value::as_object)
            .map(|slots| slots.values().filter_map(|slot| slot.get("requires")).filter_map(Value::as_array)
                .flatten().filter_map(Value::as_str).map(ToString::to_string).collect())
            .unwrap_or_default();
        requires.sort();
        requires.dedup();
        templates.push(json!({
            "templateId": entry.get("id"),
            "name": entry.get("label"),
            "runtime": "declarative",
            "gameType": entry.get("gameType"),
            "description": Value::Null,
            "genre": Value::Null,
            "tags": [],
            "compatibility": {"requiredCapabilities": requires},
            "source": {"digest": Value::Null, "entry": Value::Null},
            "license": Value::Null,
            "tests": [],
            "createTool": "creator_project_create",
        }));
    }
    let code = creator_code_template_index().get("templates").and_then(Value::as_array)
        .ok_or_else(|| ToolError::new("data_unavailable", "Code Game template index is unavailable."))?;
    for entry in code {
        let mut projected = entry.clone();
        projected["createTool"] = json!("creator_code_project_create");
        templates.push(projected);
    }
    Ok(json!({"schemaVersion":1,"templates":templates}))
}

fn spec(name: &'static str, description: &'static str, properties: Value, required: &[&str]) -> ToolSpec {
    ToolSpec {
        name,
        description,
        input_schema: json!({"type":"object","properties":properties,"required":required,"additionalProperties":false}),
        output_schema: json!({"type":"object","properties":{"ok":{"type":"boolean"},"data":{"type":"object"}}}),
    }
}

/// creator_scene_capture 的编码帧字节预算（≈256 KiB base64，图像为有界预览而非全尺寸截图）。
pub const MAX_CAPTURE_ENCODED_CHARS: usize = 350_000;

fn project_id_prop() -> Value { json!({"type":"string","minLength":1,"maxLength":128}) }
fn operation_id_prop() -> Value { json!({"type":"string","minLength":1,"maxLength":128,"description":"稳定幂等键；超时重试必须复用同一个值。"}) }
fn revision_prop() -> Value { json!({"type":"integer","minimum":0}) }

